protected void init()
{
    api = XAPI_APIS::CreateCampaignReply;
    super();
}

protected str body()
{
    smmBusRelTable  busRelTable;
    str             custAccount;
    Map             configMap;

    custAccount = XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateCustomer, 'CustAccount');

    select firstonly BusRelAccount from busRelTable
        where busRelTable.CustAccount == custAccount;

    configMap = new Map(Types::String, Types::String);
    configMap.insert('<DataAreaId>',    curExt());
    configMap.insert('<CustAccount>',   custAccount);
    configMap.insert('<BusRelAccount>', busRelTable.BusRelAccount);
    configMap.insert('<ContractNum>',   XAPI_APILogTable::getValueByKey(XAPI_APIS::CreateContract, 'ContractNum'));

    return this.prepareBody(configMap);
}
